mapper.select:
SELECT balance_after
FROM billing_ledger_entries
WHERE user_id = #{userId}
  AND account = #{account}
ORDER BY id DESC
LIMIT 1

SELECT *
FROM (
  SELECT id, user_id, account, direction, amount, biz_type, biz_id,
         idempotency_key, balance_after, remark, gmt_create
  FROM billing_ledger_entries
  WHERE user_id = #{userId}
  ORDER BY id DESC
  LIMIT #{limit}
) recent
ORDER BY recent.account ASC, recent.id ASC
